module.exports = "import React, { Component, Fragment } from 'react';\n\nimport {\n  EuiRange,\n  EuiSpacer,\n  EuiFormHelpText,\n  EuiDualRange,\n} from '../../../../src/components';\n\nimport makeId from '../../../../src/components/form/form_row/make_id';\n\nexport default class extends Component {\n  constructor(props) {\n    super(props);\n\n    this.levels = [\n      {\n        min: 0,\n        max: 20,\n        color: 'danger',\n      },\n      {\n        min: 20,\n        max: 100,\n        color: 'success',\n      },\n    ];\n\n    this.state = {\n      value: '20',\n      dualValue: [20, 100],\n    };\n  }\n\n  onChange = e => {\n    this.setState({\n      value: e.target.value,\n    });\n  };\n\n  onDualChange = value => {\n    this.setState({\n      dualValue: value,\n    });\n  };\n\n  render() {\n    return (\n      <Fragment>\n        <EuiRange\n          id={makeId()}\n          value={this.state.value}\n          onChange={this.onChange}\n          showTicks\n          tickInterval={20}\n          levels={this.levels}\n          aria-describedby=\"levelsHelp2\"\n        />\n        <EuiFormHelpText id=\"levelsHelp2\">\n          Recommended levels are {this.levels[1].min} and above.\n        </EuiFormHelpText>\n\n        <EuiSpacer size=\"xl\" />\n\n        <EuiDualRange\n          id={makeId()}\n          value={this.state.dualValue}\n          onChange={this.onDualChange}\n          showTicks\n          ticks={[{ label: '20kb', value: 20 }, { label: '100kb', value: 100 }]}\n          showInput\n          levels={this.levels}\n          aria-describedby=\"levelsHelp3\"\n        />\n        <EuiFormHelpText id=\"levelsHelp3\">\n          Recommended size is {this.levels[1].min}kb and above.\n        </EuiFormHelpText>\n      </Fragment>\n    );\n  }\n}\n"