module.exports = "import React, { Component } from 'react';\n\nimport {\n  EuiButton,\n  EuiFormRow,\n  EuiPopover,\n  EuiSwitch,\n} from '../../../../src/components';\n\nexport default class extends Component {\n  constructor(props) {\n    super(props);\n\n    this.state = {\n      isPopoverOpen: false,\n    };\n  }\n\n  onButtonClick() {\n    this.setState({\n      isPopoverOpen: !this.state.isPopoverOpen,\n    });\n  }\n\n  closePopover() {\n    this.setState({\n      isPopoverOpen: false,\n    });\n  }\n\n  render() {\n    const button = (\n      <EuiButton\n        iconType=\"arrowDown\"\n        iconSide=\"right\"\n        onClick={this.onButtonClick.bind(this)}>\n        Show popover\n      </EuiButton>\n    );\n\n    return (\n      <EuiPopover\n        id=\"trapFocus\"\n        ownFocus\n        button={button}\n        isOpen={this.state.isPopoverOpen}\n        closePopover={this.closePopover.bind(this)}\n        initialFocus=\"[id=asdf2]\">\n        <EuiFormRow label=\"Generate a public snapshot?\" id=\"asdf\">\n          <EuiSwitch name=\"switch\" label=\"Snapshot data\" />\n        </EuiFormRow>\n\n        <EuiFormRow label=\"Include the following in the embed\" id=\"asdf2\">\n          <EuiSwitch name=\"switch\" label=\"Current time range\" />\n        </EuiFormRow>\n\n        <EuiButton fill>Copy IFRAME code</EuiButton>\n      </EuiPopover>\n    );\n  }\n}\n"