module.exports = "import React, { Component } from 'react';\n\nimport { EuiButton, EuiPopover } from '../../../../src/components';\n\nexport default class PopoverContainer extends Component {\n  constructor(props) {\n    super(props);\n\n    this.state = {\n      isPopoverOpen: false,\n    };\n  }\n\n  onButtonClick = () => {\n    this.setState({\n      isPopoverOpen: !this.state.isPopoverOpen,\n    });\n  };\n\n  closePopover = () => {\n    this.setState({\n      isPopoverOpen: false,\n    });\n  };\n\n  setPanelRef = node => (this.panel = node);\n\n  render() {\n    const button = (\n      <EuiButton onClick={this.onButtonClick} fullWidth>\n        This button is expanded\n      </EuiButton>\n    );\n\n    return (\n      <EuiPopover\n        button={button}\n        isOpen={this.state.isPopoverOpen}\n        closePopover={this.closePopover}\n        display=\"block\">\n        <div>This is a popover</div>\n      </EuiPopover>\n    );\n  }\n}\n"