module.exports = "import React, { Component, Fragment } from 'react';\nimport {\n  EuiDelayRender,\n  EuiFlexItem,\n  EuiCheckbox,\n  EuiFormRow,\n  EuiFieldNumber,\n  EuiLoadingSpinner,\n} from '../../../../src/components';\n\nexport default class extends Component {\n  state = {\n    minimumDelay: 3000,\n    render: false,\n  };\n\n  onChangeMinimumDelay = event => {\n    this.setState({ minimumDelay: parseInt(event.target.value, 10) });\n  };\n\n  onChangeHide = event => {\n    this.setState({ render: event.target.checked });\n  };\n\n  render() {\n    const status = this.state.render ? 'showing' : 'hidden';\n    const label = `Child (${status})`;\n    return (\n      <Fragment>\n        <EuiFlexItem>\n          <EuiFormRow>\n            <EuiCheckbox\n              id=\"dummy-id\"\n              checked={this.state.render}\n              onChange={this.onChangeHide}\n              label=\"Show child\"\n            />\n          </EuiFormRow>\n          <EuiFormRow label=\"Minimum delay\">\n            <EuiFieldNumber\n              value={this.state.minimumDelay}\n              onChange={this.onChangeMinimumDelay}\n            />\n          </EuiFormRow>\n\n          <EuiFormRow label={label}>\n            {this.state.render ? (\n              <EuiDelayRender delay={this.state.minimumDelay}>\n                <EuiLoadingSpinner size=\"m\" />\n              </EuiDelayRender>\n            ) : (\n              <Fragment />\n            )}\n          </EuiFormRow>\n        </EuiFlexItem>\n      </Fragment>\n    );\n  }\n}\n"